import React from 'react';
import { NavLink } from 'react-router-dom';

import {
  FiHome,
  FiCalendar,
  FiImage,
  FiVideo,
  FiGrid,
  FiBookOpen,
  FiUsers,
  FiStar,
  FiMessageSquare,
  FiSettings,
  FiX,
  FiLayers,
} from 'react-icons/fi';


// ==========================================
// MENU ITEMS
// ==========================================
const menuItems = [
  {
    name: 'Dashboard',
    path: '/',
    icon: FiHome,
  },
  {
    name: 'Events',
    path: '/events',
    icon: FiCalendar,
  },
  {
    name: 'Gallery',
    path: '/gallery',
    icon: FiImage,
  },
  {
    name: 'Videos',
    path: '/videos',
    icon: FiVideo,
  },
  {
    name: 'Services',
    path: '/services',
    icon: FiGrid,
  },
  {
    name: 'Courses',
    path: '/courses',
    icon: FiBookOpen,
  },
  {
    name: 'Schools',
    path: '/schools',
    icon: FiLayers,
  },

  // ========================================
  // LEADERSHIP TEAM
  // ========================================
  {
    name: 'Leadership Team',
    path: '/leadership',
    icon: FiUsers,
  },

  {
    name: 'Testimonials',
    path: '/testimonials',
    icon: FiStar,
  },
  {
    name: 'Messages',
    path: '/messages',
    icon: FiMessageSquare,
  },
  {
    name: 'Settings',
    path: '/settings',
    icon: FiSettings,
  },
];


// ==========================================
// ADMIN SIDEBAR
// ==========================================
const AdminSidebar = ({
  isOpen = false,
  onClose,
}) => {
  return (
    <>
      {/* ======================================
          MOBILE OVERLAY
      ====================================== */}
      {isOpen && (
        <div
          className="fixed inset-0 bg-black/50 z-40 lg:hidden"
          onClick={onClose}
        />
      )}


      {/* ======================================
          SIDEBAR
      ====================================== */}
      <aside
        className={`
          fixed
          top-0
          left-0
          z-50
          h-screen
          w-64
          bg-blue-950
          text-white
          transition-transform
          duration-300
          ease-in-out
          lg:translate-x-0
          ${isOpen ? 'translate-x-0' : '-translate-x-full'}
        `}
      >

        {/* ==================================
            LOGO / HEADER
        ================================== */}
        <div className="h-20 flex items-center justify-between px-5 border-b border-white/10">

          <NavLink
            to="/"
            className="flex items-center gap-3"
            onClick={onClose}
          >

            {/* LOGO */}
            <div className="w-11 h-11 rounded-xl bg-white flex items-center justify-center text-blue-950 font-bold text-lg">
              SC
            </div>

            {/* BRAND */}
            <div>
              <h1 className="text-lg font-bold leading-tight">
                SC Academy
              </h1>

              <p className="text-xs text-blue-200">
                Admin Panel
              </p>
            </div>

          </NavLink>


          {/* MOBILE CLOSE */}
          <button
            type="button"
            onClick={onClose}
            className="
              lg:hidden
              w-9
              h-9
              flex
              items-center
              justify-center
              rounded-lg
              text-blue-200
              hover:text-white
              hover:bg-white/10
              transition
            "
          >
            <FiX size={22} />
          </button>

        </div>


        {/* ==================================
            NAVIGATION
        ================================== */}
        <nav
          className="
            px-3
            py-5
            space-y-1
            overflow-y-auto
          "
          style={{
            height: 'calc(100vh - 80px)',
          }}
        >

          {/* MENU LABEL */}
          <p className="px-3 mb-3 text-xs font-semibold uppercase tracking-wider text-blue-300">
            Management
          </p>


          {/* MENU ITEMS */}
          {menuItems.map((item) => {
            const Icon = item.icon;

            return (
              <NavLink
                key={item.path}
                to={item.path}
                end={item.path === '/'}
                onClick={onClose}
                className={({ isActive }) =>
                  `
                    group
                    flex
                    items-center
                    gap-3
                    px-4
                    py-3
                    rounded-xl
                    text-sm
                    font-medium
                    transition-all
                    duration-200

                    ${
                      isActive
                        ? `
                          bg-white
                          text-blue-950
                          shadow-md
                        `
                        : `
                          text-blue-100
                          hover:bg-white/10
                          hover:text-white
                        `
                    }
                  `
                }
              >

                {/* ICON */}
                {({ isActive }) => (
                  <>
                    <div
                      className={`
                        flex
                        items-center
                        justify-center
                        w-8
                        h-8
                        rounded-lg
                        transition

                        ${
                          isActive
                            ? 'bg-blue-100 text-blue-950'
                            : 'bg-white/5 text-blue-200 group-hover:bg-white/10 group-hover:text-white'
                        }
                      `}
                    >
                      <Icon size={18} />
                    </div>

                    <span>
                      {item.name}
                    </span>
                  </>
                )}

              </NavLink>
            );
          })}

        </nav>

      </aside>
    </>
  );
};


export default AdminSidebar;
